namespace christeye::living::plans {
namespace sha_detail {
inline constexpr std::array<std::uint32_t,64> k = {{
0x428a2f98u,0x71374491u,0xb5c0fbcfu,0xe9b5dba5u,0x3956c25bu,0x59f111f1u,0x923f82a4u,0xab1c5ed5u,
0xd807aa98u,0x12835b01u,0x243185beu,0x550c7dc3u,0x72be5d74u,0x80deb1feu,0x9bdc06a7u,0xc19bf174u,
0xe49b69c1u,0xefbe4786u,0x0fc19dc6u,0x240ca1ccu,0x2de92c6fu,0x4a7484aau,0x5cb0a9dcu,0x76f988dau,
0x983e5152u,0xa831c66du,0xb00327c8u,0xbf597fc7u,0xc6e00bf3u,0xd5a79147u,0x06ca6351u,0x14292967u,
0x27b70a85u,0x2e1b2138u,0x4d2c6dfcu,0x53380d13u,0x650a7354u,0x766a0abbu,0x81c2c92eu,0x92722c85u,
0xa2bfe8a1u,0xa81a664bu,0xc24b8b70u,0xc76c51a3u,0xd192e819u,0xd6990624u,0xf40e3585u,0x106aa070u,
0x19a4c116u,0x1e376c08u,0x2748774cu,0x34b0bcb5u,0x391c0cb3u,0x4ed8aa4au,0x5b9cca4fu,0x682e6ff3u,
0x748f82eeu,0x78a5636fu,0x84c87814u,0x8cc70208u,0x90befffau,0xa4506cebu,0xbef9a3f7u,0xc67178f2u}};
constexpr std::uint32_t rotr(std::uint32_t v, unsigned n) noexcept { return (v>>n)|(v<<(32-n)); }
}
class Sha256 {
  std::array<std::uint32_t,8> h_{{0x6a09e667u,0xbb67ae85u,0x3c6ef372u,0xa54ff53au,
                                 0x510e527fu,0x9b05688cu,0x1f83d9abu,0x5be0cd19u}};
  std::array<std::uint8_t,64> buffer_{};
  std::size_t used_ = 0;
  std::uint64_t total_ = 0;
  void block(const std::uint8_t* p) noexcept {
    std::array<std::uint32_t,64> w{};
    for(unsigned i=0;i<16;++i)
      w[i] = (std::uint32_t(p[4*i])<<24) | (std::uint32_t(p[4*i+1])<<16) |
             (std::uint32_t(p[4*i+2])<<8) | std::uint32_t(p[4*i+3]);
    for(unsigned i=16;i<64;++i){
      auto a=w[i-15],b=w[i-2];
      w[i]=(sha_detail::rotr(b,17)^sha_detail::rotr(b,19)^(b>>10))+w[i-7]+
           (sha_detail::rotr(a,7)^sha_detail::rotr(a,18)^(a>>3))+w[i-16];
    }
    auto a=h_[0],b=h_[1],c=h_[2],d=h_[3],e=h_[4],f=h_[5],g=h_[6],h=h_[7];
    for(unsigned i=0;i<64;++i){
      auto s1=sha_detail::rotr(e,6)^sha_detail::rotr(e,11)^sha_detail::rotr(e,25);
      auto choose=(e&f)^((~e)&g);
      auto t1=h+s1+choose+sha_detail::k[i]+w[i];
      auto s0=sha_detail::rotr(a,2)^sha_detail::rotr(a,13)^sha_detail::rotr(a,22);
      auto majority=(a&b)^(a&c)^(b&c);
      auto t2=s0+majority;
      h=g;g=f;f=e;e=d+t1;d=c;c=b;b=a;a=t1+t2;
    }
    h_[0]+=a;h_[1]+=b;h_[2]+=c;h_[3]+=d;h_[4]+=e;h_[5]+=f;h_[6]+=g;h_[7]+=h;
  }
public:
  void update(std::string_view text) noexcept {
    for(char character : text){
      const auto byte=static_cast<unsigned char>(character);
      buffer_[used_++]=byte;
      ++total_;
      if(used_==64){block(buffer_.data());used_=0;}
    }
  }
  std::string hex() const noexcept {
    Sha256 copy=*this;
    const std::uint64_t length_bits=copy.total_*8;
    copy.buffer_[copy.used_++]=0x80u;
    if(copy.used_>56){
      while(copy.used_<64)copy.buffer_[copy.used_++]=0;
      copy.block(copy.buffer_.data());copy.used_=0;
    }
    while(copy.used_<56)copy.buffer_[copy.used_++]=0;
    for(unsigned i=0;i<8;++i)copy.buffer_[56+i]=std::uint8_t(length_bits>>(56-8*i));
    copy.block(copy.buffer_.data());
    static constexpr char digits[]="0123456789abcdef";
    std::string text;
    text.reserve(64);
    for(auto v:copy.h_)
      for(int shift=28;shift>=0;shift-=4) text+=digits[(v>>shift)&0xfu];
    return text;
  }
};
inline std::string sha256_hex(std::string_view bytes) noexcept {
  Sha256 h;h.update(bytes);return h.hex();
}
}
